"""Original fixed tasks closing the detailed MGSU fallback syllabus gaps.
Call append_supplement before stable-ID assignment. All activities are virtual.
"""
import math


def append_supplement(tasks, calc, choice, sources):
    sources.update({
        'colloids': 'https://openstax.org/books/chemistry-2e/pages/11-5-colloids',
        'surface': 'https://openstax.org/books/chemistry-2e/pages/10-2-properties-of-liquids',
        'adsorption': 'https://goldbook.iupac.org/terms/view/A00155',
        'arrhenius': 'https://openstax.org/books/chemistry-2e/pages/12-5-collision-theory',
        'organic': 'https://openstax.org/books/chemistry-2e/pages/20-3-aldehydes-ketones-carboxylic-acids-and-esters',
        'alcohols': 'https://openstax.org/books/chemistry-2e/pages/20-2-alcohols-and-ethers',
        'chain': 'https://openstax.org/books/organic-chemistry/pages/31-1-chain-growth-polymers',
        'step': 'https://openstax.org/books/organic-chemistry/pages/31-4-step-growth-polymers',
        'colligative': 'https://openstax.org/books/chemistry-2e/pages/11-4-colligative-properties',
        'gas': 'https://openstax.org/books/chemistry-2e/pages/9-2-relating-pressure-volume-amount-and-temperature-the-ideal-gas-law',
    })
    start = len(tasks)

    def concept(module, family, prompt, correct, wrong, why, topic, source, **kw):
        level = 3 if module == 6 else 5
        choice(level, module, family, prompt, correct, wrong, why, source=source, difficulty=2, **kw)
        tasks[-1]['topic'] = topic

    phases = [
        ('капли жидкости в газе', 'аэрозоль', ['эмульсия', 'пена', 'твёрдый раствор']),
        ('пузырьки газа в жидкости', 'пена', ['эмульсия', 'раствор соли', 'аэрозоль']),
        ('капли одной жидкости в другой несмешивающейся жидкости', 'эмульсия', ['газовая смесь', 'твёрдый раствор', 'пена']),
        ('твёрдые коллоидные частицы в жидкости', 'золь', ['пена', 'газовая смесь', 'молекулярный раствор']),
        ('твёрдые частицы в газе', 'твёрдый аэрозоль', ['эмульсия', 'пена', 'ионный раствор']),
        ('пузырьки газа в твёрдой матрице', 'твёрдая пена', ['эмульсия', 'золь', 'молекулярный раствор']),
    ]
    for state, correct, wrong in phases:
        concept(6, 'Классификация дисперсных систем', f'В виртуальном образце дисперсная фаза — {state}. Как классифицировать систему по фазам?', correct, wrong,
                f'Агрегатное состояние частиц и непрерывной среды определяет тип системы: {state} — {correct}. Размер частиц оценивают отдельно.', 'Дисперсные системы', 'colloids')
    observations = [
        ('частицы растворённого вещества представлены отдельными ионами и молекулами', 'истинный раствор', ['коллоидная дисперсия', 'грубая суспензия', 'пена'], 'Истинный раствор однороден на молекулярном или ионном уровне.'),
        ('мелкие частицы рассеивают боковой луч и устойчиво распределены в жидкости', 'коллоидная дисперсия', ['идеальный газ', 'кристалл соли', 'истинный раствор'], 'Коллоидные частицы могут рассеивать свет и длительно сохраняться в дисперсии.'),
        ('крупные твёрдые частицы при отстаивании образуют осадок', 'грубая суспензия', ['молекулярный раствор', 'газовая смесь', 'кристаллическая решётка'], 'Осаждение крупных взвешенных частиц характерно для грубодисперсной суспензии.'),
        ('дисперсные частицы слипаются в более крупные агрегаты', 'коагуляция', ['диссоциация молекул', 'испарение среды', 'идеальное растворение'], 'Коагуляция означает объединение частиц дисперсной фазы в агрегаты.'),
    ]
    for readout, correct, wrong, why in observations:
        concept(6, 'Наблюдение дисперсной пробы', f'Виртуальная микромодель: {readout}. Выбери вывод.', correct, wrong, why,
                'Дисперсные системы', 'colloids', station='inspection-station')
    for prompt, correct, wrong, why in [
        ('В виртуальной модели крупные частицы разделяются на более мелкие без изменения состава. Как называется принцип образования дисперсии?', 'диспергирование', ['конденсационное укрупнение молекул', 'электролиз', 'полимеризация'], 'Диспергирование уменьшает размеры исходных частиц.'),
        ('В виртуальной модели молекулы объединяются до коллоидного размера без образования крупных оседающих частиц. Как называется подход?', 'конденсационный', ['механическое дробление', 'фильтрация осадка', 'испарение готового сорбента'], 'Конденсационный подход формирует частицы из меньших единиц; задан предел коллоидного размера.'),
        ('В модельной эмульсии масляные капли распределены в непрерывной воде. Что является дисперсной фазой?', 'масляные капли', ['непрерывная вода', 'вся посуда', 'только граница рисунка'], 'Дисперсная фаза представлена отдельными каплями; вода служит непрерывной средой.'),
        ('В модельном золе твёрдые частицы распределены в непрерывной воде. Что является дисперсионной средой?', 'вода', ['твёрдые частицы', 'только электроны', 'воздух за пределами образца'], 'Дисперсионная среда — непрерывная фаза, в которой распределены частицы.'),
    ]:
        concept(6, 'Фаза и образование дисперсии', prompt, correct, wrong, why, 'Дисперсные системы', 'colloids')
    for angle in [25, 60, 110, 140]:
        hydrophilic = angle < 90
        concept(6, 'Смачивание поверхности', f'Модель гладкой однородной поверхности: равновесный краевой угол воды {angle}°, отсчитанный внутри капли. Используй границу 90°. Какова поверхность?',
                'гидрофильная' if hydrophilic else 'гидрофобная',
                ['гидрофобная' if hydrophilic else 'гидрофильная', 'краевой угол равен нулю', 'по условию угол равен 180°'],
                f'В заданной классификации угол {angle}° {"меньше" if hydrophilic else "больше"} 90°: поверхность {"гидрофильная" if hydrophilic else "гидрофобная"}. Шероховатость и гистерезис в модели исключены.',
                'Поверхностные явления', 'surface')
    surface_cases = [
        ('Молекулы вещества преимущественно накапливаются на поверхности виртуального пористого сорбента. Как называется процесс?', 'адсорбция', ['испарение', 'электролиз', 'кристаллизация всего сорбента'], 'Адсорбция относится к накоплению вещества на границе фаз.', 'adsorption'),
        ('В модели одна часть молекулы ПАВ притягивается к воде, другая — к масляной капле. Как назвать строение?', 'амфифильное', ['только гидрофильное', 'только гидрофобное', 'металлическое'], 'Амфифильная молекула сочетает гидрофильный участок и гидрофобный участок.', 'colloids'),
        ('В виртуальной эмульсии добавка препятствует слиянию масляных капель. Какова её роль?', 'эмульгатор', ['окислитель металла', 'источник электронного тока', 'растворитель стальной арматуры'], 'Эмульгатор стабилизирует распределение капель и препятствует их слиянию.', 'colloids'),
        ('В модели одинаково заряженные коллоидные частицы отталкиваются. Как это влияет на их слипание?', 'препятствует сближению и агрегации', ['обязательно превращает их в газ', 'создаёт ковалентную сетку', 'нейтрализует все ионы раствора'], 'Электростатическое отталкивание может поддерживать агрегативную устойчивость; состояние среды также влияет на неё.', 'colloids'),
    ]
    for prompt, correct, wrong, why, source in surface_cases:
        concept(6, 'Поверхность и устойчивость', prompt, correct, wrong, why, 'Поверхностные явления', source)
    organic = [
        ('CH3CH2OH', 'спирт', ['простой эфир', 'альдегид', 'карбоновая кислота'], 'Группа OH связана с насыщенным атомом углерода.', 'alcohols'),
        ('CH3OCH3', 'простой эфир', ['спирт', 'кетон', 'карбоновая кислота'], 'Атом кислорода соединяет два углеродных заместителя.', 'alcohols'),
        ('CH3CHO', 'альдегид', ['кетон', 'спирт', 'сложный эфир'], 'Карбонильный атом углерода группы CHO связан с водородом.', 'organic'),
        ('CH3COCH3', 'кетон', ['альдегид', 'спирт', 'карбоновая кислота'], 'Карбонильная группа соединена с двумя углеродными заместителями.', 'organic'),
        ('CH3COOH', 'карбоновая кислота', ['кетон', 'простой эфир', 'альдегид'], 'Функциональная группа COOH — карбоксильная.', 'organic'),
        ('CH3COOCH3', 'сложный эфир', ['простой эфир', 'спирт', 'альдегид'], 'Фрагмент C(=O)–O–C характерен для сложного эфира.', 'organic'),
    ]
    for formula, correct, wrong, why, source in organic:
        concept(13, 'Функциональные группы', f'На виртуальной карточке структурная формула {formula}. Определи класс вещества.', correct, wrong, why, 'Органическая химия', source)
    polymers = [
        ('При идеализированной цепной полимеризации этилена CH2=CH2 какой фрагмент повторяется в основной цепи?', '–CH2–CH2–', ['–CH=CH–', '–CO–O–', '–Si–O–'], 'При присоединении этилена двойная связь раскрывается, образуя звено полиэтилена.', 'chain'),
        ('Какой мономер соответствует идеализированному звену полипропилена –CH2–CH(CH3)–?', 'CH2=CH–CH3', ['CH2=CH2', 'CH3OH', 'CH3COOH'], 'Боковая группа CH3 сохраняется при цепном присоединении пропилена.', 'chain'),
        ('В учебной схеме диол и дикарбоновая кислота образуют полиэфир с удалением воды. Как классифицировать образование цепи?', 'поликонденсация', ['испарение готового полимера', 'ионная диссоциация', 'электролиз'], 'При образовании сложноэфирных связей в заданной схеме выделяется низкомолекулярный продукт — вода.', 'step'),
        ('В модели полиамида цепь растёт через образование связей –CO–NH– между аминными и карбоксильными группами с выделением воды. Какова связь между звеньями?', 'амидная', ['ионная решётка NaCl', 'металлическая', 'только водородная'], 'Фрагмент –CO–NH– представляет ковалентную амидную связь основной цепи.', 'step'),
    ]
    for prompt, correct, wrong, why, source in polymers:
        concept(13, 'Образование полимерной цепи', prompt, correct, wrong, why, 'Полимерные материалы', source)
    for Ea in [25000, 40000, 50000, 60000]:
        variables = {'E': Ea, 'R': 8.314, 'T1': 300, 'T2': 320}
        expr = 'exp(E/R*(1/T1-1/T2))'
        calc(4, 9, 'Уравнение Аррениуса', f'В модели Аррениуса Ea={Ea} Дж/моль, R=8.314 Дж/(моль·К), T1=300 К, T2=320 К. Предэкспоненциальный множитель и Ea постоянны. Найди k2/k1.',
             math.exp(Ea/8.314*(1/300-1/320)), '', 'k2/k1 = exp[(Ea/R)(1/T1 − 1/T2)]. Температуры используют в К.', expr, variables, source='arrhenius', station='reaction-bench')
    for gamma, delta in [(2, 10), (2, 20), (3, 10), (3, 20)]:
        calc(4, 9, 'Температурный коэффициент', f'Для ограниченного интервала модели задано: при каждых +10 К скорость умножается на γ={gamma}. Остальные условия постоянны. Найди отношение скоростей при нагреве на {delta} К.',
             gamma**(delta/10), '', 'В заданной эмпирической модели v2/v1 = γ^(ΔT/10); это приближение для указанного интервала.', 'g**(d/10)', {'g': gamma, 'd': delta}, source='arrhenius', station='reaction-bench')
    for molality in [.1, .2, .3, .5]:
        calc(3, 6, 'Повышение температуры кипения', f'Идеальный разбавленный водный раствор нелетучего неэлектролита: b={molality} моль/кг, Kb=0.512 К·кг/моль, i=1. Найди повышение температуры кипения при неизменном давлении.',
             .512*molality, 'К', 'ΔTb = i Kb b. Величина положительна для заданного растворённого вещества.', 'i*K*b', {'i':1, 'K':.512, 'b':molality}, source='colligative')
    for amount in [.1, .2, .3, .5]:
        calc(3, 6, 'Идеальный газ', f'Виртуальная проба идеального газа: n={amount} моль, T=300 К, p=100 кПа. Используй R=8.314 л·кПа/(моль·К). Найди объём.',
             amount*8.314*300/100, 'л', 'pV=nRT; V=nRT/p. Используй согласованные единицы и абсолютную температуру.', 'n*R*T/p', {'n':amount, 'R':8.314, 'T':300, 'p':100}, source='gas')
    assert len(tasks)-start == 48, len(tasks)-start
